---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER"

-- Applications
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + Space",  hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + L",      hl.dsp.exec_cmd("noctalia msg session lock"))
hl.bind(mainMod .. " + E",      hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + Q",      hl.dsp.window.close())

-- Audio and Media
hl.bind(mainMod .. " + ALT + Z", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true })
hl.bind("Pause",                 hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind(mainMod .. " + ALT + Space", hl.dsp.exec_cmd("playerctl stop"), { locked = true })
hl.bind(mainMod .. " + ALT + minus", hl.dsp.exec_cmd("playerctl previous"), { locked = true })
hl.bind(mainMod .. " + ALT + equal", hl.dsp.exec_cmd("playerctl next"), { locked = true })

-- Overview
hl.bind(mainMod .. " + Tab", hl.dsp.exec_cmd("noctalia msg panel-toggle overview"))

-- Focus Window
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "l" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "r" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "u" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "d" }))

-- Move Window
hl.bind(mainMod .. " + CTRL + left",  hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + CTRL + right", hl.dsp.window.move({ direction = "r" }))
hl.bind(mainMod .. " + CTRL + up",    hl.dsp.window.move({ direction = "u" }))
hl.bind(mainMod .. " + CTRL + down",  hl.dsp.window.move({ direction = "d" }))
hl.bind(mainMod .. " + CTRL + H",     hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + CTRL + L",     hl.dsp.window.move({ direction = "r" }))
hl.bind(mainMod .. " + CTRL + K",     hl.dsp.window.move({ direction = "u" }))
hl.bind(mainMod .. " + CTRL + J",     hl.dsp.window.move({ direction = "d" }))

-- Focus Monitor
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.exec_cmd("hyprctl dispatch focusmonitor l"))
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.exec_cmd("hyprctl dispatch focusmonitor r"))
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.exec_cmd("hyprctl dispatch focusmonitor u"))
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.exec_cmd("hyprctl dispatch focusmonitor d"))
hl.bind(mainMod .. " + SHIFT + H",     hl.dsp.exec_cmd("hyprctl dispatch focusmonitor l"))
hl.bind(mainMod .. " + SHIFT + L",     hl.dsp.exec_cmd("hyprctl dispatch focusmonitor r"))
hl.bind(mainMod .. " + SHIFT + K",     hl.dsp.exec_cmd("hyprctl dispatch focusmonitor u"))
hl.bind(mainMod .. " + SHIFT + J",     hl.dsp.exec_cmd("hyprctl dispatch focusmonitor d"))

-- Move Window to Monitor
hl.bind(mainMod .. " + SHIFT + CTRL + left",  hl.dsp.exec_cmd("hyprctl dispatch movewindowmon l"))
hl.bind(mainMod .. " + SHIFT + CTRL + right", hl.dsp.exec_cmd("hyprctl dispatch movewindowmon r"))
hl.bind(mainMod .. " + SHIFT + CTRL + up",    hl.dsp.exec_cmd("hyprctl dispatch movewindowmon u"))
hl.bind(mainMod .. " + SHIFT + CTRL + down",  hl.dsp.exec_cmd("hyprctl dispatch movewindowmon d"))
hl.bind(mainMod .. " + SHIFT + CTRL + H",     hl.dsp.exec_cmd("hyprctl dispatch movewindowmon l"))
hl.bind(mainMod .. " + SHIFT + CTRL + L",     hl.dsp.exec_cmd("hyprctl dispatch movewindowmon r"))
hl.bind(mainMod .. " + SHIFT + CTRL + K",     hl.dsp.exec_cmd("hyprctl dispatch movewindowmon u"))
hl.bind(mainMod .. " + SHIFT + CTRL + J",     hl.dsp.exec_cmd("hyprctl dispatch movewindowmon d"))

-- Workspaces
for i = 1, 9 do
    hl.bind(mainMod .. " + " .. i,        hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + CTRL + " .. i, hl.dsp.window.move({ workspace = i }))
end

-- Relative Workspaces
hl.bind(mainMod .. " + U",         hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mainMod .. " + Page_Down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + Page_Up",   hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mainMod .. " + I",         hl.dsp.focus({ workspace = "e+1" }))

hl.bind(mainMod .. " + CTRL + U",         hl.dsp.window.move({ workspace = "e-1" }))
hl.bind(mainMod .. " + CTRL + Page_Down", hl.dsp.window.move({ workspace = "e+1" }))
hl.bind(mainMod .. " + CTRL + Page_Up",   hl.dsp.window.move({ workspace = "e-1" }))
hl.bind(mainMod .. " + CTRL + I",         hl.dsp.window.move({ workspace = "e+1" }))

hl.bind(mainMod .. " + SHIFT + U",         hl.dsp.window.move({ workspace = "e-1" }))
hl.bind(mainMod .. " + SHIFT + Page_Down", hl.dsp.window.move({ workspace = "e+1" }))
hl.bind(mainMod .. " + SHIFT + Page_Up",   hl.dsp.window.move({ workspace = "e-1" }))
hl.bind(mainMod .. " + SHIFT + I",         hl.dsp.window.move({ workspace = "e+1" }))

-- Window State
hl.bind(mainMod .. " + F",         hl.dsp.exec_cmd("hyprctl dispatch fullscreen 1")) -- maximize
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.exec_cmd("hyprctl dispatch fullscreen 0")) -- true fullscreen
hl.bind(mainMod .. " + M",         hl.dsp.exec_cmd("hyprctl dispatch fullscreen 0"))
hl.bind(mainMod .. " + X",         hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + C",         hl.dsp.exec_cmd("hyprctl dispatch centerwindow"))

-- Special keys
hl.bind("Print",                   hl.dsp.exec_cmd("noctalia msg screenshot-fullscreen"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_cmd("noctalia msg screenshot-region"))
hl.bind("ALT + Print",             hl.dsp.exec_cmd("noctalia msg screenshot-window"))

hl.bind(mainMod .. " + V",         hl.dsp.exec_cmd("noctalia msg panel-toggle clipboard"))
hl.bind(mainMod .. " + BackSpace", hl.dsp.exec_cmd("noctalia msg panel-toggle session"))

hl.bind("CTRL + ALT + Delete", hl.dsp.exit())
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.exec_cmd("hyprctl dispatch dpms off"))

-- Mouse Binds
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mainMod .. " + mouse:272",  hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273",  hl.dsp.window.resize(), { mouse = true })

